def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        base = 18.0 if hp > 3 else 40.0
        return min(budget, base)

    prev_bids = []
    desperate_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opponents += 1
        if opp.get('budget', 0) >= budget:
            rich_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0

    if supply >= 22:
        base = 20.0
    elif supply >= 19:
        base = 28.0
    else:
        base = 40.0

    if hp <= 2:
        base = max(base, 60.0)
    elif hp <= 4:
        base += 8.0

    if no_water >= 2:
        base = max(base, 65.0)
    elif no_water >= 1:
        base += 10.0

    if desperate_opponents > 0:
        base += 6.0 * desperate_opponents
    if rich_opponents >= len(alive_opponents) / 2.0:
        base += 4.0

    if highest_prev > 0:
        if highest_prev >= 60:
            if hp > 4 and no_water == 0 and supply >= 20:
                base = min(base, 26.0)
            else:
                base = max(base, min(68.0, highest_prev + 2.0))
        else:
            base = max(base, highest_prev + 1.5)

    if day >= 8:
        base += 6.0

    if budget < 35:
        base = min(base, budget)
    else:
        base = min(base, budget, 0.75 * budget)

    if base < 0:
        base = 0
    return float(base)
